CREATE TABLE accounts (id uuid PRIMARY KEY, mail_address text UNIQUE, clerk_user_id text UNIQUE, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profiles (id uuid PRIMARY KEY, account_id uuid NOT NULL REFERENCES accounts(id), name text, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profile_metadata (profile_id uuid PRIMARY KEY REFERENCES profiles(id), height_cm double precision, date_of_birth text, people_type text, gender text, profile_image text, preferred_body_fat_pct double precision NOT NULL DEFAULT 18, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE jobs (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), status text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at timestamptz, result text, error text);
CREATE TABLE measurements (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), weight double precision, heart_rate integer, impedance double precision, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE body_measurements (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), neck_cm double precision, shoulder_cm double precision, chest_cm double precision, stomach_cm double precision, waist_cm double precision, calf_cm double precision, thigh_cm double precision, bicep_cm double precision, forearm_cm double precision, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, CHECK (num_nonnulls(neck_cm, shoulder_cm, chest_cm, stomach_cm, waist_cm, calf_cm, thigh_cm, bicep_cm, forearm_cm) > 0));
CREATE TABLE body_composition_metrics (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), body_fat_pct double precision NOT NULL, muscle_mass_kg double precision NOT NULL, water_pct double precision NOT NULL, protein_pct double precision NOT NULL, fat_free_mass_kg double precision NOT NULL, fat_mass_kg double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE body_composition_metrics_new (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), bmi double precision NOT NULL, body_fat_pct double precision NOT NULL, fat_mass_kg double precision NOT NULL, fat_free_mass_kg double precision NOT NULL, desired_weight_kg double precision, body_score integer NOT NULL, body_age_years integer NOT NULL, water_pct double precision NOT NULL, muscle_mass_kg double precision NOT NULL, muscle_rate_pct double precision NOT NULL, bmr_kcal integer NOT NULL, visceral_fat integer NOT NULL, ideal_weight_kg double precision NOT NULL, protein_mass_kg double precision NOT NULL, protein_pct double precision NOT NULL, skeletal_muscle_kg double precision NOT NULL, subcutaneous_fat_pct double precision NOT NULL, subcutaneous_fat_mass_kg double precision NOT NULL, predicted_lean_mass_kg double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE derived_body_composition_metrics (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), fmi double precision NOT NULL, ffmi double precision NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE progress_measurements (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id), name text NOT NULL, value double precision NOT NULL, unit text NOT NULL DEFAULT 'cm', notes text NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE workouts (id uuid PRIMARY KEY, source_workout_id text NOT NULL UNIQUE, profile_id uuid REFERENCES profiles(id) ON DELETE SET NULL, name text NOT NULL, location text, is_indoor boolean, started_at timestamptz, ended_at timestamptz, duration_seconds double precision, distance_qty double precision, distance_units text, active_energy_qty double precision, active_energy_units text, total_energy_qty double precision, total_energy_units text, avg_heart_rate_qty double precision, avg_heart_rate_units text, min_heart_rate_qty double precision, min_heart_rate_units text, max_heart_rate_qty double precision, max_heart_rate_units text, speed_qty double precision, speed_units text, step_cadence_qty double precision, step_cadence_units text, intensity_qty double precision, intensity_units text, temperature_qty double precision, temperature_units text, humidity_qty double precision, humidity_units text, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, raw_payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profile_ai_overviews (profile_id uuid PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE, overview_title text NOT NULL, overview_remarks text NOT NULL, foundation jsonb NOT NULL, momentum jsonb NOT NULL, biggest_lever jsonb NOT NULL, physique_archetype text NOT NULL, model_name text, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profile_effort_scores (profile_id uuid PRIMARY KEY REFERENCES profiles(id) ON DELETE CASCADE, score integer NOT NULL CHECK(score BETWEEN 0 AND 100), remark text NOT NULL, model_name text, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE derived_metrics_comments (id uuid PRIMARY KEY, profile_id uuid NOT NULL UNIQUE REFERENCES profiles(id) ON DELETE CASCADE, ffmi jsonb NOT NULL, ffmi_vs_fmi jsonb NOT NULL, composition_flow jsonb NOT NULL, composition_trend jsonb NOT NULL, recomp_vector jsonb NOT NULL, excess_fat_gauge jsonb NOT NULL, body_ratios jsonb NOT NULL, model_name text, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reports (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, lab_name text, report_date text, collection_date text, extraction_status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE report_sections (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, section_name_raw text NOT NULL, section_name_normalized text);
CREATE TABLE observation_fields (id uuid PRIMARY KEY, field_name text NOT NULL, field_name_normalized text NOT NULL UNIQUE, explanation text NOT NULL DEFAULT '', default_unit text, is_trendable boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE observation_field_remarks (id uuid PRIMARY KEY, observation_field_id uuid NOT NULL UNIQUE REFERENCES observation_fields(id) ON DELETE CASCADE, remark text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE observations (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES reports(id) ON DELETE CASCADE, section_id uuid REFERENCES report_sections(id) ON DELETE SET NULL, observation_field_id uuid REFERENCES observation_fields(id) ON DELETE SET NULL, test_name_raw text NOT NULL, test_name_normalized text, value_raw text NOT NULL, value_numeric double precision, value_text text, unit_raw text, unit_normalized text, reference_range_raw text, ref_low double precision, ref_high double precision, inference text NOT NULL DEFAULT '', confidence_score double precision CHECK(confidence_score IS NULL OR confidence_score BETWEEN 0 AND 1), created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE performance_reports (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, body_composition_metrics_id uuid NOT NULL UNIQUE REFERENCES body_composition_metrics_new(id) ON DELETE CASCADE, fmi double precision, ffmi double precision, model_name text, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE performance_report_comments (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES performance_reports(id) ON DELETE CASCADE, factor text NOT NULL, remark text NOT NULL DEFAULT '', comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profile_insight_reports (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, body_composition_metrics_id uuid NOT NULL UNIQUE REFERENCES body_composition_metrics_new(id) ON DELETE CASCADE, overview_title text, overview_remarks text, foundation jsonb, momentum jsonb, biggest_lever jsonb, physique_archetype text, effort_score integer CHECK(effort_score IS NULL OR effort_score BETWEEN 0 AND 100), effort_remark text, model_name text, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profile_insight_report_comments (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES profile_insight_reports(id) ON DELETE CASCADE, factor text NOT NULL, remark text NOT NULL DEFAULT '', comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fat_reports (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, body_composition_metrics_id uuid NOT NULL UNIQUE REFERENCES body_composition_metrics_new(id) ON DELETE CASCADE, fat_percent double precision NOT NULL, visceral_fat_delta_30d_kg double precision NOT NULL, subcutaneous_fat_delta_30d_kg double precision NOT NULL, fat_mass_kg double precision NOT NULL, visceral_fat_mass_kg double precision NOT NULL, visceral_fat_percent double precision NOT NULL, subcutaneous_fat_mass_kg double precision NOT NULL, subcutaneous_fat_ratio double precision NOT NULL, model_name text, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE fat_report_comments (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES fat_reports(id) ON DELETE CASCADE, factor text NOT NULL, remark text NOT NULL DEFAULT '', comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE muscle_reports (id uuid PRIMARY KEY, profile_id uuid NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, body_composition_metrics_id uuid NOT NULL UNIQUE REFERENCES body_composition_metrics_new(id) ON DELETE CASCADE, total_muscle_kg double precision NOT NULL, bone_mass_kg double precision NOT NULL, muscle_ratio double precision NOT NULL, skeletal_muscle_mass_kg double precision NOT NULL, skeletal_muscle_ratio double precision NOT NULL, model_name text, created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE muscle_report_comments (id uuid PRIMARY KEY, report_id uuid NOT NULL REFERENCES muscle_reports(id) ON DELETE CASCADE, factor text NOT NULL, remark text NOT NULL DEFAULT '', comment text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX idx_reports_profile_report_date ON reports(profile_id, report_date DESC, created_at DESC);
CREATE INDEX idx_reports_extraction_status ON reports(extraction_status);
CREATE INDEX idx_report_sections_report_id ON report_sections(report_id);
CREATE INDEX idx_observation_fields_name ON observation_fields(field_name_normalized);
CREATE INDEX idx_observation_field_remarks_field ON observation_field_remarks(observation_field_id);
CREATE INDEX idx_observations_report ON observations(report_id);
CREATE INDEX idx_observations_section ON observations(section_id);
CREATE INDEX idx_observations_test_name ON observations(test_name_normalized);
CREATE INDEX idx_observations_observation_field ON observations(observation_field_id);
CREATE INDEX idx_performance_reports_profile_created ON performance_reports(profile_id, created_at DESC);
CREATE INDEX idx_performance_report_comments_report ON performance_report_comments(report_id);
CREATE INDEX idx_profile_insight_reports_profile_created ON profile_insight_reports(profile_id, created_at DESC);
CREATE INDEX idx_profile_insight_report_comments_report ON profile_insight_report_comments(report_id);
CREATE INDEX idx_fat_reports_profile_created ON fat_reports(profile_id, created_at DESC);
CREATE INDEX idx_fat_report_comments_report ON fat_report_comments(report_id);
CREATE INDEX idx_muscle_reports_profile_created ON muscle_reports(profile_id, created_at DESC);
CREATE INDEX idx_muscle_report_comments_report ON muscle_report_comments(report_id);
